document.documentElement.classList.add('js');const reduce=matchMedia('(prefers-reduced-motion: reduce)');const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}},{threshold:.08});document.querySelectorAll('.section-heading,.project-card,.center-heading,.experience-grid,.about-copy,.linkedin-card').forEach((el,i)=>{el.classList.add('reveal');el.style.transitionDelay=(i%3)*70+'ms';observer.observe(el)});
const composition=document.querySelector('.composition');composition.addEventListener('pointermove',e=>{if(reduce.matches||e.pointerType==='touch')return;const r=composition.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;composition.querySelectorAll('[data-depth]').forEach(el=>{el.style.setProperty('--mx',x*el.dataset.depth+'px');el.style.setProperty('--my',y*el.dataset.depth+'px')})});composition.addEventListener('pointerleave',()=>{composition.querySelectorAll('[data-depth]').forEach(el=>{el.style.setProperty('--mx','0px');el.style.setProperty('--my','0px')})});document.querySelectorAll('.letter-key').forEach(key=>key.addEventListener('click',()=>{document.querySelectorAll('.selection,.name-cursor').forEach(el=>{el.getAnimations().forEach(a=>{a.cancel();a.play()})})}));
const tabs={ios:'Building Pullar with SwiftUI and SwiftData. Learning through real app development, from tracking transactions to organizing spending insights.',python:'Learning Python and artificial intelligence alongside computing fundamentals at RIT Dubai. Exploring how ideas become useful software.',design:'My background includes graphic design. I’m interested in making app interfaces clearer, easier to use, and more enjoyable.'};document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b))});document.querySelector('#experience-text').textContent=tabs[b.dataset.tab]}));
const dialog=document.querySelector('dialog');document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const pullar=b.dataset.project==='pullar';document.querySelector('#dialog-title').textContent=pullar?'Pullar':b.dataset.project==='two'?'Next idea':'In the making';document.querySelector('#dialog-label').textContent=pullar?'Personal project · Swift / SwiftUI / SwiftData':'PROJECT PLACEHOLDER';document.querySelector('#dialog-content').innerHTML=pullar?'<p>A personal finance app built with SwiftUI and SwiftData to help track and understand everyday spending.</p><ul><li>Income and expense tracking</li><li>Custom categories</li><li>Charts and calendar summaries</li><li>Record export and backup restoration</li></ul><p>App screenshots, process images, and the full case study are placeholders until you add them.</p>':'<p>Add your project description, role, process, screenshots, and links here.</p>';dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
